231	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String reason) {
232	        Claim claim = lock(sheetId, claimId);
233	        refuseClosed(sheetId, claim.getDueBy());
234	        String voidReason = to == ClaimStatus.VOID ? voidReasons.required(sheetId, reason) : null;
235	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
236	            return voidSettled(sheetId, user, claim, voidReason);
237	        }
238	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
239	            throw new ResponseStatusException(HttpStatus.CONFLICT,
240	                    "A " + claim.getStatus() + " claim cannot become " + to);
241	        }
242	        String action = switch (to) {
243	            case OPEN -> "open";
244	            case SETTLED -> "settle";
245	            default -> "void";
246	        };
247	        if (!roles.may(sheetId, user, action)) {
248	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
249	        }
250	        if (to == ClaimStatus.OPEN) {
251	            refuseUnnoted(sheetId, claim);
252	        }
253	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
254	            throw new ResponseStatusException(HttpStatus.CONFLICT,
255	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
256	        }
257	        if (to == ClaimStatus.SETTLED && claim.openedOrEditedBy(user)) {
258	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
259	                    "The user who opened or last edited a claim cannot settle it");
260	        }
261	        if (to == ClaimStatus.SETTLED) {
262	            refuseUnproved(sheetId, claim);
263	        }
264	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
265	                ? ClaimStatus.PENDING : to;
266	        return rollup.tracking(sheetId, user, () -> {
267	            Person person = person(sheetId, claim.getPersonId());
268	            if (becomes == ClaimStatus.SETTLED) {
269	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
270	                // statement bound it to, if any, and its late charge); later changes to rates, the
271	                // late percent and the sheet's today do not alter it.
272	                claim.setSettledDue(dues.figure(sheetId, person, claim));
273	            }
274	            // A void claim keeps the number it had (never reused).
275	            claim.setStatus(becomes);
276	            if (becomes == ClaimStatus.VOID) {
277	                claim.setVoidReason(voidReason);
278	            }
279	            if (becomes == ClaimStatus.OPEN) {
280	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
281	                claim.setOpenedBy(user);
282	            }
283	            logStatus(sheetId, user, person, claim);
284	            Claim saved = claims.saveAndFlush(claim);
285	            String event = switch (becomes) {
286	                case OPEN -> "CLAIM_OPENED";
287	                case PENDING -> "CLAIM_PENDING";
288	                case SETTLED -> "CLAIM_SETTLED";
289	                case VOID -> "CLAIM_VOIDED";
290	                case DRAFT, DELETED -> throw new IllegalStateException("a claim is deleted or restored apart");
291	            };
292	            String line = record(event, sheetId, user, person, saved);
293	            if (becomes == ClaimStatus.SETTLED) {
294	                line += " due=" + dueText(saved.getSettledDue());
295	            }
296	            line += reasonText(voidReason);
297	            audit.recordOnCommit(line);
298	            if (becomes == ClaimStatus.SETTLED) {
299	                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
300	            }
301	            return saved;
302	        });
303	    }
