353	     *  settlement (the first SETTLED line of its status log) by the sheet's today. It keeps its
354	     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
355	    private Claim voidSettled(String sheetId, String user, Claim claim, String voidReason) {
356	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
