364	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
365	        }
366	        return rollup.tracking(sheetId, user, () -> {
367	            Person person = person(sheetId, claim.getPersonId());
368	            BigDecimal reversed = dues.figure(sheetId, person, claim);
369	            claim.setStatus(ClaimStatus.VOID);
370	            claim.setVoidReason(voidReason);
371	            logStatus(sheetId, user, person, claim);
372	            Claim saved = claims.saveAndFlush(claim);
373	            audit.recordOnCommit(record("CLAIM_VOIDED", sheetId, user, person, saved) + " reversed=" + dueText(reversed)
374	                    + reasonText(voidReason));
375	            return saved;
376	        });
377	    }
